+import { randomUUID } from 'node:crypto';
+
+const FINISHED = new Set(['completed', 'failed']);
+
+export class ExecutionTasks {
+  constructor({ now = Date.now, limit = 200, retentionMs = 60 * 60_000 } = {}) {
+    this.tasks = new Map();
+    this.now = now;
+    this.limit = limit;
+    this.retentionMs = retentionMs;
+  }
+
+  prune() {
+    for (const [id, task] of this.tasks) {
+      if (FINISHED.has(task.status) && this.now() - task.finishedAt > this.retentionMs) {
+        this.tasks.delete(id);
+      }
+    }
+    for (const [id, task] of this.tasks) {
+      if (this.tasks.size < this.limit) break;
+      if (FINISHED.has(task.status)) this.tasks.delete(id);
+    }
+  }
+
+  create(windowId, operation = 'execute', documentUuid) {
+    this.prune();
+    if (this.tasks.size >= this.limit) {
+      throw Object.assign(new Error('Task capacity reached; unresolved executions are retained.'), { statusCode: 429 });
+    }
+    const task = {
+      id: randomUUID(), windowId, operation, documentUuid,
+      status: 'submitted', phase: 'submitted', progress: null,
+      createdAt: this.now(), updatedAt: this.now(), events: [],
+    };
+    this.tasks.set(task.id, task);
+    return task;
+  }
+
+  event(id, windowId, event) {
+    const task = this.tasks.get(id);
+    if (!task || task.windowId !== windowId || FINISHED.has(task.status)) return false;
+    const timestamp = this.now();
+    task.updatedAt = timestamp;
+    if (event.type === 'progress') {
+      task.status = 'running';
+      task.startedAt ??= timestamp;
+      task.phase = typeof event.phase === 'string' ? event.phase : task.phase;
+      task.progress = event.progress ?? null;
+      if (typeof event.warning === 'string') task.warning = event.warning;
+    }
+    task.events.push({ ...event, timestamp });
+    if (task.events.length > 100) task.events.shift();
+    return true;
+  }
+
+  finish(id, windowId, message) {
+    const task = this.tasks.get(id);
+    if (!task || task.windowId !== windowId || FINISHED.has(task.status)) return false;
+    task.status = message.type === 'result' ? 'completed' : 'failed';
+    task.finishedAt = task.updatedAt = this.now();
+    delete task.warning;
+    if (message.type === 'result') {
+      task.result = message.result;
+    } else {
+      task.error = message.error || 'Unknown EDA error';
+      task.errorDetails = message.errorDetails;
+    }
+    return true;
+  }
+
+  disconnect(windowId) {
+    for (const task of this.tasks.values()) {
+      if (task.windowId !== windowId || FINISHED.has(task.status)) continue;
+      task.status = 'unknown';
+      task.updatedAt = this.now();
+      task.warning = 'Connection lost. Execution may still be running in EDA; do not automatically retry.';
+    }
+  }
+
+  get(id) {
+    const task = this.tasks.get(id);
+    if (!task) return undefined;
+    return { ...task, elapsedMs: (task.finishedAt ?? this.now()) - task.createdAt };
+  }
+
+  list() {
+    return [...this.tasks.keys()].map(id => this.get(id));
+  }
+}

