+import test, { before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { once } from 'node:events';
+import { WebSocket } from 'ws';
+import { httpServer, wss } from '../scripts/bridge-server.mjs';
+
+let base;
+const sockets = new Set();
+before(async () => {
+  httpServer.listen(0, '127.0.0.1');
+  await once(httpServer, 'listening');
+  base = `http://127.0.0.1:${httpServer.address().port}`;
+});
+after(async () => {
+  for (const socket of sockets) socket.terminate();
+  for (const client of wss.clients) client.terminate();
+  await new Promise(resolve => wss.close(resolve));
+  await new Promise(resolve => httpServer.close(resolve));
+});
+
+const get = async path => (await fetch(base + path)).json();
+async function post(path, payload) {
+  const response = await fetch(base + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload), signal: AbortSignal.timeout(path === '/execute' ? 33_000 : 3000) });
+  return { status: response.status, body: await response.json() };
+}
+
+async function until(fn) {
+  for (let i = 0; i < 100; i++) {
+    const result = await fn();
+    if (result) return result;
+    await new Promise(resolve => setTimeout(resolve, 10));
+  }
+  throw new Error('Condition was not reached');
+}
+
+async function connect(id, capabilities = []) {
+  const socket = new WebSocket(base.replace('http:', 'ws:') + '/eda');
+  sockets.add(socket);
+  await once(socket, 'open');
+  socket.send(JSON.stringify({ type: 'register', windowId: id, capabilities }));
+  await until(async () => (await get('/eda-windows')).windows.some(window => window.windowId === id));
+  return socket;
+}
+
+test('disconnected requests and invalid JSON return useful HTTP errors', async () => {
+  assert.equal((await post('/tasks', { code: 'return true;', windowId: 'missing' })).status, 503);
+  assert.equal((await post('/tasks', null)).status, 400);
+  const response = await fetch(base + '/tasks', { method: 'POST', body: '{' });
+  assert.equal(response.status, 400);
+  const misplaced = await post('/routing', { documentUuid: 'pcb', nets: ['GND'] });
+  assert.equal(misplaced.status, 400);
+  assert.match(misplaced.body.error, /Unknown routing request fields/);
+});
+
+test('old gateways accept general tasks but refuse unsupported routing requests', async () => {
+  const socket = await connect('old');
+  assert.equal((await post('/routing', { windowId: 'old', documentUuid: 'pcb' })).status, 409);
+  socket.on('message', raw => {
+    const message = JSON.parse(raw);
+    if (message.type === 'execute') socket.send(JSON.stringify({ type: 'result', id: message.id, result: false }));
+  });
+  const { status, body } = await post('/tasks', { windowId: 'old', code: 'return false;' });
+  assert.equal(status, 202);
+  const task = await until(async () => { const task = await get(body.statusUrl); return task.status === 'completed' && task; });
+  assert.equal(task.result, false);
+});
+
+test('async routing exposes progress and does not confuse partial routing with full completion', async () => {
+  const socket = await connect('router', ['routing-v1']);
+  let request;
+  socket.on('message', raw => {
+    request = JSON.parse(raw);
+    socket.send(JSON.stringify({ type: 'progress', id: request.id, phase: 'routing', progress: null }));
