+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { ExecutionTasks } from '../scripts/execution-tasks.mjs';
+
+test('long-running tasks retain elapsed time, progress and late results', () => {
+  let time = 1000;
+  const tasks = new ExecutionTasks({ now: () => time });
+  const task = tasks.create('pcb-window', 'autoRouting', 'pcb');
+  tasks.event(task.id, 'pcb-window', { type: 'progress', phase: 'routing', progress: null });
+  time += 90_000;
+  assert.equal(tasks.get(task.id).elapsedMs, 90_000);
+  assert.equal(tasks.get(task.id).status, 'running');
+  assert.equal(tasks.get(task.id).progress, null);
+  tasks.finish(task.id, 'pcb-window', { type: 'result', result: { outcome: 'partial', failedNets: ['VCC'] } });
+  time += 10_000;
+  assert.equal(tasks.get(task.id).elapsedMs, 90_000);
+  assert.equal(tasks.get(task.id).result.outcome, 'partial');
+});
+
+test('messages from another window cannot complete or update a task', () => {
+  const tasks = new ExecutionTasks();
+  const task = tasks.create('a');
+  assert.equal(tasks.event(task.id, 'b', { type: 'progress' }), false);
+  assert.equal(tasks.finish(task.id, 'b', { type: 'result', result: true }), false);
+  assert.equal(tasks.get(task.id).status, 'submitted');
+});
+
+test('disconnect means unknown, not failed or cancelled', () => {
+  const tasks = new ExecutionTasks();
+  const task = tasks.create('a');
+  tasks.disconnect('a');
+  assert.equal(tasks.get(task.id).status, 'unknown');
+  assert.match(tasks.get(task.id).warning, /may still be running/);
+});
+
+test('completed tasks cannot be overwritten by late progress or duplicate results', () => {
+  const tasks = new ExecutionTasks();
+  const task = tasks.create('a');
