+import { readFile } from 'node:fs/promises';
+import vm from 'node:vm';
+import { randomUUID } from 'node:crypto';
+
+const bundle = await readFile(process.env.EASYEDA_GATEWAY_BUNDLE || new URL('../../../eext-run-api-gateway/dist/index.js', import.meta.url), 'utf8');
