+export function createGateway({ send, connect, routing, clearRouting, document, nets, selection = ['pad-1'], apiAvailable = true, routingEnumsAvailable = true } = {}) {
+  let messageCallback;
+  const intervals = new Set();
+  const timeouts = new Set();
+  const services = new Map();
+  const output = [];
+  const calls = [];
+  const currentDocument = document || (() => ({ uuid: 'pcb-test', documentType: 3 }));
+  const eda = {
+    sys_WebSocket: {
+      register(_id, url, callback) {
+        messageCallback = callback;
+        connect?.(url);
+      },
+      close() {},
+      send(_id, data) {
+        const message = JSON.parse(data);
+        output.push(message);
+        send?.(message);
+        return true;
+      },
+    },
+    sys_Message: { showToastMessage() {} },
+    sys_I18n: { text: value => value },
+    sys_Storage: { getExtensionUserConfig: () => false },
+    sys_MessageBus: {
+      rpcService: (name, fn) => services.set(name, fn),
+      rpcCall: async (name, arg) => services.get(name)?.(arg),
+    },
+    sys_Dialog: { showInformationMessage() {} },
+    sys_Environment: { getEditorCurrentVersion: () => '3.2.186' },
+    dmt_SelectControl: { getCurrentDocumentInfo: async () => currentDocument() },
+    pcb_Net: { getAllNetsName: async () => nets || ['VCC', 'GND'] },
+    pcb_SelectControl: { getAllSelectedPrimitives_PrimitiveId: async () => selection },
+    pcb_Document: {
+      autoRouting: apiAvailable ? async props => {
+        calls.push({ operation: 'autoRouting', props });
+        return routing ? routing(props) : { success: true, totalNetsCount: 2, successNetsCount: 2, failedNets: [], duration: 12 };
+      } : undefined,
+      clearRouting: async type => {
+        calls.push({ operation: 'clearRouting', type });
+        return clearRouting ? clearRouting(type) : true;
+      },
+    },
+  };
+  const context = vm.createContext({
+    eda, console, crypto: { randomUUID },
+    ESYS_ToastMessageType: { ERROR: 'error' },
+    EDMT_EditorDocumentType: { PCB: 3 },
+    EPCB_LayerId: { TOP: 1, BOTTOM: 2, INNER_1: 15, INNER_30: 44 },
+    EPCB_AutoRoutingCornerStyle: { DEGREE_45: 0, DEGREE_90: 1 },
+    EPCB_AutoRoutingOptimization: { COMPLETION: 1, FASTER: 0 },
+    EPCB_AutoRoutingExistingPrimitiveMode: { KEEP: 'keep', REMOVE: 'remove' },
+    setTimeout: (fn, ms) => {
+      const timer = setTimeout(() => { timeouts.delete(timer); fn(); }, ms);
+      timeouts.add(timer);
+      return timer;
+    },
+    clearTimeout: timer => { clearTimeout(timer); timeouts.delete(timer); },
+    setInterval: (fn, ms) => { const timer = setInterval(fn, ms); intervals.add(timer); return timer; },
+    clearInterval: timer => { clearInterval(timer); intervals.delete(timer); },
+  });
+  if (!routingEnumsAvailable) {
+    delete context.EPCB_AutoRoutingCornerStyle;
+    delete context.EPCB_AutoRoutingOptimization;
+    delete context.EPCB_AutoRoutingExistingPrimitiveMode;
+  }
+  vm.runInContext(bundle, context);
+  const api = context.edaEsbuildExportName;
+  api.activate();
+  api.reconnect();
+  return {
+    api, eda, output, calls,
+    receive: message => messageCallback({ data: JSON.stringify(message) }),
+    ready: async () => {
+      await new Promise(resolve => setImmediate(resolve));
+      await messageCallback({ data: JSON.stringify({ type: 'handshake', service: 'easyeda-bridge' }) });
+    },
+    close() {
+      api.deactivate();
+      for (const timer of intervals) clearInterval(timer);
+      for (const timer of timeouts) clearTimeout(timer);
+    },
+  };
+}

