+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createGateway } from './gateway-harness.mjs';
+
+async function setup(t, options) {
+  const gateway = createGateway(options);
+  t.after(() => gateway.close());
+  await gateway.ready();
+  return gateway;
+}
+
+const route = (routing = {}, id = 'route-1') => ({ type: 'routing', id, routing: { operation: 'autoRouting', documentUuid: 'pcb-test', ...routing } });
+const final = gateway => gateway.output.filter(msg => msg.type === 'result' || msg.type === 'error').at(-1);
+
+test('automatic routing reports stages and final counts without invented percentages', async t => {
+  const gateway = await setup(t);
+  await gateway.receive(route({ props: { RoutingNets: ['VCC'] } }));
+  assert.equal(final(gateway).result.outcome, 'complete');
+  assert.equal(final(gateway).result.successNetsCount, 2);
+  assert.deepEqual(gateway.output.filter(msg => msg.type === 'progress').map(msg => msg.phase), ['preflight', 'routing', 'complete']);
+  assert.ok(gateway.output.filter(msg => msg.type === 'progress').every(msg => msg.progress === null));
+});
+
+test('success true with failed or unfinished networks is partial completion', async t => {
+  const gateway = await setup(t, { routing: () => ({ success: true, totalNetsCount: 2, successNetsCount: 1, failedNets: ['GND'], duration: 50 }) });
+  await gateway.receive(route());
+  assert.equal(final(gateway).result.outcome, 'partial');
+  assert.deepEqual(final(gateway).result.failedNets, ['GND']);
+});
+
+test('success false preserves the native result as a startup failure', async t => {
+  const gateway = await setup(t, { routing: () => ({ success: false, failedNets: ['VCC'] }) });
+  await gateway.receive(route());
